parameters.jsonBody:
={{ (() => {
  const d = $json.data;
  const line = (label, val) => `${label}: ${val}`;
  const listOrNone = (arr, fmt) => arr.length ? arr.map((x, i) => `${i + 1}. ${fmt(x)}`).join('
') : 'None';
  const header = `DAILY OFFICE CALL SUMMARY
Date: ${d.date}

` +
    `${line('Total Calls', d.totalCalls)}
${line('Urgent Calls', d.urgentCalls)}
` +
    `${line('Callback Requests', d.callbackRequests)}
${line('Appointments Requested', d.appointmentsRequested)}
` +
    `${line('Follow-ups Pending', d.followUpsPending)}
`;
  const urgent = `
URGENT CALLS
` + listOrNone(d.urgent, x => `${x.callerName || 'Unknown'} (${x.organization || 'N/A'}) — ${x.summary || 'No summary'} [${x.urgencyLevel}${x.deadline ? ', due ' + x.deadline : ''}]`);
  const callbacks = `

CALLBACK REQUESTS
` + listOrNone(d.callbacks, x => `${x.callerName || 'Unknown'} — ${x.callbackNumber || 'N/A'} — ${x.message || ''}`);
  const appts = `

APPOINTMENT REQUESTS
` + listOrNone(d.appointments, x => `${x.callerName || 'Unknown'} — ${x.requestedDate || 'TBD'} ${x.requestedTime || ''} — ${x.notes || ''}`);
  const other = `

OTHER IMPORTANT CALLS
` + listOrNone(d.otherImportant, x => `${x.callerName || 'Unknown'} — ${x.summary || ''} (${x.intent})`);
  const followups = `

FOLLOW-UP ITEMS
` + listOrNone(d.followUps, x => `${x.callerName || 'Unknown'} — due ${x.dueAt || 'N/A'} — ${x.notes || ''}`);
  return { from: 'AI Receptionist <onboarding@resend.dev>', to: [d.recipientEmail], subject: `Daily Office Call Summary — ${d.date}`, text: header + urgent + callbacks + appts + other + followups };
})() }}
